// Resize canvas to fill parent
  const resize = () => {
    canvas.width = canvas.clientWidth;
    canvas.height = canvas.clientHeight;
  };
  resize();
  window.addEventListener('resize', resize);

  // ----- Player ship -----
  const ship = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    size: 15,
    speed: 2.5,
    vx: 0,
    vy: 0,
  };

  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key.toLowerCase()] = true; });
  window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

  const updateShip = () => {
    if (keys['arrowleft'] || keys['a']) ship.vx = -ship.speed;
    else if (keys['arrowright'] || keys['d']) ship.vx = ship.speed;
    else ship.vx = 0;

    if (keys['arrowup'] || keys['w']) ship.vy = -ship.speed;
    else if (keys['arrowdown'] || keys['s']) ship.vy = ship.speed;
    else ship.vy = 0;

    ship.x = Math.max(ship.size, Math.min(canvas.width - ship.size, ship.x + ship.vx));
    ship.y = Math.max(ship.size, Math.min(canvas.height - ship.size, ship.y + ship.vy));
  };

  const drawShip = () => {
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(0, -ship.size);
    ctx.lineTo(ship.size / 2, ship.size);
    ctx.lineTo(-ship.size / 2, ship.size);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  };

